import { useAuth } from "@/_core/hooks/useAuth";
import { Button } from "@/components/ui/button";
import { CaseReportButton } from "@/components/CaseSubmissionDialog";
import { MARKETPLACE_PAGE_SIZE, naira } from "@/lib/marketplace";
import { trpc } from "@/lib/trpc";
import { Bell, BellRing, CalendarClock, Eye, EyeOff, Flag, Gavel, Heart, LockKeyhole, MessageCircle, Pencil, Search, ShieldCheck, Star, Store, Trash2 } from "lucide-react";
import { FormEvent, useState } from "react";
import { Link, useLocation, useRoute } from "wouter";
import { toast } from "sonner";

const format = (value: string) => value.replaceAll("_", " ");
type ReviewPhoto = { filename: string; mimeType: "image/jpeg" | "image/png" | "image/webp"; dataUrl: string };
const reviewPhotoTypes = new Set(["image/jpeg", "image/png", "image/webp"]);
const readReviewPhoto = (file: File) => new Promise<ReviewPhoto>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve({ filename: file.name, mimeType: file.type as ReviewPhoto["mimeType"], dataUrl: String(reader.result) }); reader.onerror = () => reject(new Error("The selected review image could not be read.")); reader.readAsDataURL(file); });
function Gate({ children }: { children: React.ReactNode }) { const { isAuthenticated } = useAuth(); return isAuthenticated ? <>{children}</> : <main className="page-shell py-20 text-center"><p className="eyebrow justify-center text-[#00843d]">ESUT MARKETPLACE</p><h1 className="mt-3 text-3xl font-extrabold">Sign in to access this area</h1><p className="mx-auto mt-3 max-w-md text-sm text-slate-600">Your account keeps orders, saved listings, messages, and seller progress together in one secure workspace.</p><div className="mt-6 flex flex-wrap justify-center gap-3"><Link href="/login"><Button className="bg-[#e31b23]">Log in</Button></Link><Link href="/register"><Button variant="outline">Create account</Button></Link><Link href="/"><Button variant="ghost">Back to marketplace</Button></Link></div></main>; }
export function VerifiedSellerRouteGate({ children }: { children: React.ReactNode }) { const { user, loading } = useAuth(); if (loading) return <main className="page-shell py-16">Loading seller workspace…</main>; if (user?.role === "SELLER") return <>{children}</>; if (user?.role === "ADMIN" || user?.role === "SUPER_ADMIN") return <main className="page-shell py-20 text-center"><ShieldCheck className="mx-auto text-[#00843d]" size={42} /><h1 className="mt-4 text-3xl font-extrabold">Administrator control center only</h1><p className="mx-auto mt-2 max-w-xl text-slate-600">Administrator accounts manage and monitor ESUT Marketplace from the control center. Seller self-service tools are not available to administrators.</p><div className="mt-6 flex flex-wrap justify-center gap-3"><Link href="/admin"><Button className="bg-[#00843d]">Open control center</Button></Link><Link href="/admin/operations"><Button variant="outline">View operations</Button></Link></div></main>; return <main className="page-shell py-20 text-center"><Store className="mx-auto text-[#00843d]" size={42} /><h1 className="mt-4 text-3xl font-extrabold">Seller approval required</h1><p className="mx-auto mt-2 max-w-xl text-slate-600">These seller tools unlock only after seller verification and administrator approval. Your buyer account remains available while you complete onboarding.</p><div className="mt-6 flex flex-wrap justify-center gap-3"><Link href="/sell"><Button className="bg-[#e31b23]">Continue seller onboarding</Button></Link><Link href="/account"><Button variant="outline">Return to buyer account</Button></Link></div></main>; }

export function BuyerFavoritesPage() {
  const favorites = trpc.favorites.list.useQuery(); const utils = trpc.useUtils(); const toggle = trpc.favorites.toggle.useMutation({ onSuccess: () => utils.favorites.list.invalidate(), onError: error => toast.error(error.message) }); const moveToCart = trpc.cart.add.useMutation({ onSuccess: () => { toast.success("Added to your cart."); utils.cart.get.invalidate(); }, onError: error => toast.error(error.message) });
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#e31b23]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">Saved favorites</h1><section className="mt-7 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">{favorites.isLoading ? <p className="col-span-full rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading saved favorites…</p> : favorites.isError ? <div className="col-span-full rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load favorites.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => favorites.refetch()}>Try again</Button></div> : favorites.data?.length ? favorites.data.map(({ listing, store, image }) => <article key={listing.id} className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><Link href={`/product/${listing.slug}`}>{image?.url ? <img src={image.url} alt={listing.title} className="h-44 w-full object-cover" /> : <div className="h-44 bg-slate-100" />}</Link><div className="p-5"><p className="font-extrabold">{listing.title}</p><p className="mt-1 text-sm text-slate-500">{store.name}</p><div className="mt-4 flex flex-wrap items-center justify-between gap-2"><b>{naira(listing.priceKobo)}</b><div className="flex gap-2"><Button size="sm" className="bg-[#00843d]" disabled={moveToCart.isPending} onClick={() => moveToCart.mutate({ listingId: listing.id, quantity: 1 })}>{moveToCart.isPending ? "Adding…" : "Move to cart"}</Button><Button size="sm" variant="outline" disabled={toggle.isPending} onClick={() => toggle.mutate({ listingId: listing.id })}><Heart size={16} fill="currentColor" />Remove</Button></div></div></div></article>) : <p className="col-span-full rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Save products from the catalogue to compare them later.</p>}</section></main></Gate>;
}

export function BuyerRemindersPage() {
  type ReminderType = "TOMORROW" | "THREE_DAYS" | "ONE_WEEK" | "CUSTOM";
  const reminders = trpc.reminders.listMine.useQuery(); const utils = trpc.useUtils(); const [editing, setEditing] = useState<{ id: number; reminderType: ReminderType; scheduledFor: string; note: string } | null>(null);
  const refresh = () => { void utils.reminders.listMine.invalidate(); void utils.reminders.forListing.invalidate(); void utils.notifications.unreadCount.invalidate(); };
  const update = trpc.reminders.update.useMutation({ onSuccess: () => { toast.success("Reminder updated."); setEditing(null); refresh(); }, onError: error => toast.error(error.message) }); const cancel = trpc.reminders.cancel.useMutation({ onSuccess: () => { toast.success("Reminder cancelled."); refresh(); }, onError: error => toast.error(error.message) }); const remove = trpc.reminders.delete.useMutation({ onSuccess: () => { toast.success("Reminder removed."); refresh(); }, onError: error => toast.error(error.message) });
  const localDateTime = (date: Date) => new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#e31b23]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">My product reminders</h1><p className="mt-2 max-w-2xl text-sm text-slate-600">Reminders never reserve stock. We show live product availability when your reminder is due.</p><section className="mt-7 grid gap-4 lg:grid-cols-2">{reminders.isLoading ? <p className="col-span-full rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading your product reminders…</p> : reminders.isError ? <div className="col-span-full rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load your reminders.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => reminders.refetch()}>Try again</Button></div> : reminders.data?.length ? reminders.data.map(({ reminder, listing, store, image, availability }) => <article key={reminder.id} className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div className="flex gap-4 p-5">{image?.url ? <img src={image.url} alt={image.altText || listing.title} className="h-20 w-20 rounded-xl object-cover"/> : <div className="h-20 w-20 rounded-xl bg-[#eaf7ef]"/>}<div className="min-w-0 flex-1"><p className="font-extrabold">{listing.title}</p><p className="mt-1 text-sm text-slate-500">{store?.name ?? "Original store unavailable"} · {naira(listing.priceKobo)}</p><p className="mt-2 text-sm font-bold text-[#006b32]">{reminder.status === "ACTIVE" ? `Scheduled ${new Date(reminder.scheduledFor).toLocaleString()}` : reminder.status === "TRIGGERED" ? "Reminder sent" : reminder.status === "CANCELLED" ? "Cancelled" : "Currently unavailable"}</p><p className="mt-1 text-xs text-slate-500">{availability.status === "IN_STOCK" ? `${availability.availableUnits} in stock` : availability.status === "LOW_STOCK" ? `${availability.availableUnits} left — low stock` : "Currently unavailable"}</p></div></div>{editing?.id === reminder.id ? <form onSubmit={event => { event.preventDefault(); update.mutate({ id: reminder.id, reminderType: editing.reminderType, scheduledFor: editing.reminderType === "CUSTOM" ? new Date(editing.scheduledFor) : undefined, note: editing.note || undefined }); }} className="border-t bg-[#fff7e6] p-5"><label className="block text-sm font-bold">Reminder timing<select value={editing.reminderType} onChange={event => setEditing({ ...editing, reminderType: event.target.value as ReminderType })} className="mt-2 w-full rounded-xl border bg-white p-3"><option value="TOMORROW">Tomorrow</option><option value="THREE_DAYS">In 3 days</option><option value="ONE_WEEK">In 1 week</option><option value="CUSTOM">Choose date &amp; time</option></select></label>{editing.reminderType === "CUSTOM" && <label className="mt-3 block text-sm font-bold">Date and time<input required type="datetime-local" value={editing.scheduledFor} onChange={event => setEditing({ ...editing, scheduledFor: event.target.value })} className="mt-2 w-full rounded-xl border bg-white p-3"/></label>}<label className="mt-3 block text-sm font-bold">Optional note<input value={editing.note} maxLength={500} onChange={event => setEditing({ ...editing, note: event.target.value })} className="mt-2 w-full rounded-xl border bg-white p-3" placeholder="Why are you reminding yourself?"/></label><div className="mt-4 flex gap-2"><Button size="sm" className="bg-[#00843d]" disabled={update.isPending}>{update.isPending ? "Saving…" : "Save changes"}</Button><Button type="button" size="sm" variant="outline" onClick={() => setEditing(null)}>Cancel</Button></div></form> : <div className="flex flex-wrap gap-2 border-t p-4">{listing.status === "ACTIVE" && store?.status === "ACTIVE" ? <Link href={`/product/${listing.slug}`}><Button size="sm" className="bg-[#00843d]">View product</Button></Link> : <Link href={store?.status === "ACTIVE" ? `/store/${store.slug}` : `/explore?q=${encodeURIComponent(listing.title)}`}><Button size="sm" variant="outline">{store?.status === "ACTIVE" ? "View store" : "See similar products"}</Button></Link>}{reminder.status === "ACTIVE" && <Button size="sm" variant="outline" disabled={cancel.isPending} onClick={() => cancel.mutate({ id: reminder.id })}>Cancel reminder</Button>}{reminder.status === "ACTIVE" && <Button size="sm" variant="outline" onClick={() => setEditing({ id: reminder.id, reminderType: reminder.reminderType, scheduledFor: localDateTime(new Date(reminder.scheduledFor)), note: reminder.note ?? "" })}>Edit</Button>}{reminder.status !== "ACTIVE" && <Button size="sm" variant="outline" disabled={remove.isPending} onClick={() => remove.mutate({ id: reminder.id })}>Delete</Button>}</div>}</article>) : <div className="col-span-full rounded-2xl border border-dashed border-slate-300 bg-white p-8 text-center"><Bell className="mx-auto text-[#00843d]"/><p className="mt-3 font-extrabold">No product reminders yet</p><p className="mt-1 text-sm text-slate-500">Use Remind Me from a product page when you are not ready to buy.</p><Link href="/explore"><Button className="mt-5 bg-[#e31b23]">Browse products</Button></Link></div>}</section></main></Gate>;
}

export function BuyerSearchAlertsPage() {
  type AlertEdit = { id: number; query: string; categorySlug: string; minNaira: string; maxNaira: string; condition: "" | "NEW" | "LIKE_NEW" | "USED_GOOD" | "USED_FAIR" | "REFURBISHED"; verified: boolean; notifyInApp: boolean; notifyEmail: boolean };
  const alerts = trpc.searchAlerts.listMine.useQuery();
  const categories = trpc.marketplace.categories.useQuery();
  const utils = trpc.useUtils();
  const [editing, setEditing] = useState<AlertEdit | null>(null);
  const update = trpc.searchAlerts.update.useMutation({ onSuccess: () => { toast.success("Saved search updated."); setEditing(null); void utils.searchAlerts.listMine.invalidate(); }, onError: error => toast.error(error.message) });
  const cancel = trpc.searchAlerts.cancel.useMutation({ onSuccess: () => { toast.success("Saved search removed."); void utils.searchAlerts.listMine.invalidate(); }, onError: error => toast.error(error.message) });
  const activeAlerts = alerts.data?.filter(alert => alert.status === "ACTIVE") ?? [];
  const formatCriteria = (alert: (typeof activeAlerts)[number]) => [alert.categorySlug ? alert.categorySlug.replaceAll("-", " ") : null, alert.minKobo != null ? `from ${naira(alert.minKobo)}` : null, alert.maxKobo != null ? `up to ${naira(alert.maxKobo)}` : null, alert.condition ? alert.condition.replaceAll("_", " ").toLocaleLowerCase() : null, alert.verified ? "verified sellers" : null].filter(Boolean).join(" · ");
  const beginEdit = (alert: (typeof activeAlerts)[number]) => setEditing({ id: alert.id, query: alert.query, categorySlug: alert.categorySlug ?? "", minNaira: alert.minKobo == null ? "" : String(alert.minKobo / 100), maxNaira: alert.maxKobo == null ? "" : String(alert.maxKobo / 100), condition: (alert.condition ?? "") as AlertEdit["condition"], verified: alert.verified, notifyInApp: alert.notifyInApp, notifyEmail: alert.notifyEmail });
  const saveEdit = (event: FormEvent) => { event.preventDefault(); if (!editing) return; if (!editing.notifyInApp && !editing.notifyEmail) { toast.error("Choose at least one notification channel."); return; } const min = editing.minNaira.trim() ? Math.round(Number(editing.minNaira) * 100) : undefined; const max = editing.maxNaira.trim() ? Math.round(Number(editing.maxNaira) * 100) : undefined; if (min !== undefined && (!Number.isFinite(min) || min < 0) || max !== undefined && (!Number.isFinite(max) || max <= 0)) { toast.error("Enter valid price limits."); return; } update.mutate({ id: editing.id, query: editing.query, categorySlug: editing.categorySlug || undefined, minKobo: min, maxKobo: max, condition: editing.condition || undefined, verified: editing.verified, notifyInApp: editing.notifyInApp, notifyEmail: editing.notifyEmail }); };
  const removeAlert = (id: number) => { if (window.confirm("Remove this saved search? You will no longer receive alerts for it.")) cancel.mutate({ id }); };
  return <Gate><main className="page-shell py-8"><Link href="/account" className="inline-flex items-center text-sm font-bold text-[#00843d] underline-offset-4 hover:underline">← Back to account</Link><p className="eyebrow mt-5 text-[#e31b23]">MY ACCOUNT</p><div className="mt-2 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-3xl font-extrabold">Saved search alerts</h1><p className="mt-2 max-w-2xl text-sm text-slate-600">Manage the searches you asked us to watch. We will notify you when an eligible listing is published.</p></div><Link href="/explore"><Button className="bg-[#e31b23]"><Search size={16} className="mr-2"/>Find more items</Button></Link></div><section className="mt-7 rounded-3xl bg-[#eaf7ef] p-5 ring-1 ring-[#00843d]/15 sm:p-6"><div className="flex items-start gap-3"><div className="rounded-2xl bg-white p-3 text-[#00843d] shadow-sm"><BellRing size={22}/></div><div><p className="font-extrabold text-[#08243b]">Stay ahead of new campus listings</p><p className="mt-1 text-sm leading-6 text-slate-600">Alerts match your saved search words and filters. You can edit delivery channels at any time; saving one never reserves stock.</p></div></div></section><section aria-labelledby="active-search-alerts" className="mt-7"><div className="flex items-center justify-between gap-3"><div><h2 id="active-search-alerts" className="text-xl font-black">Active alerts</h2><p className="mt-1 text-sm text-slate-500">{activeAlerts.length} active {activeAlerts.length === 1 ? "search" : "searches"}</p></div></div>{alerts.isLoading ? <div className="mt-4 grid gap-4 lg:grid-cols-2">{[1, 2].map(item => <div key={item} className="h-52 animate-pulse rounded-2xl bg-slate-100 motion-reduce:animate-none" aria-hidden="true"/> )}</div> : alerts.isError ? <div className="mt-4 rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]" role="alert"><p className="font-extrabold">We could not load your saved searches.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => alerts.refetch()}>Try again</Button></div> : activeAlerts.length ? <div className="mt-4 grid gap-4 lg:grid-cols-2">{activeAlerts.map(alert => <article key={alert.id} className="rounded-2xl bg-white p-5 shadow-sm ring-1 ring-slate-200">{editing?.id === alert.id ? <form onSubmit={saveEdit} className="space-y-4"><div className="flex items-center justify-between gap-3"><h3 className="text-lg font-extrabold text-[#08243b]">Edit saved search</h3><span className="rounded-full bg-[#eaf7ef] px-2.5 py-1 text-xs font-black text-[#006b32]">ACTIVE</span></div><label className="block text-sm font-bold">Search words<input required minLength={2} maxLength={120} value={editing.query} onChange={event => setEditing({ ...editing, query: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 p-3 font-normal outline-none focus:border-[#00843d]"/></label><label className="block text-sm font-bold">Category<select value={editing.categorySlug} onChange={event => setEditing({ ...editing, categorySlug: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 bg-white p-3 font-normal outline-none focus:border-[#00843d]"><option value="">All categories</option>{categories.data?.map(category => <option key={category.id} value={category.slug}>{category.name}</option>)}</select></label><div className="grid gap-3 sm:grid-cols-2"><label className="block text-sm font-bold">Minimum price (₦)<input inputMode="decimal" value={editing.minNaira} onChange={event => setEditing({ ...editing, minNaira: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 p-3 font-normal outline-none focus:border-[#00843d]" placeholder="No minimum"/></label><label className="block text-sm font-bold">Maximum price (₦)<input inputMode="decimal" value={editing.maxNaira} onChange={event => setEditing({ ...editing, maxNaira: event.target.value })} className="mt-2 w-full rounded-xl border border-slate-200 p-3 font-normal outline-none focus:border-[#00843d]" placeholder="No maximum"/></label></div><label className="block text-sm font-bold">Condition<select value={editing.condition} onChange={event => setEditing({ ...editing, condition: event.target.value as AlertEdit["condition"] })} className="mt-2 w-full rounded-xl border border-slate-200 bg-white p-3 font-normal outline-none focus:border-[#00843d]"><option value="">Any condition</option><option value="NEW">New</option><option value="LIKE_NEW">Like new</option><option value="USED_GOOD">Used — good</option><option value="USED_FAIR">Used — fair</option><option value="REFURBISHED">Refurbished</option></select></label><label className="flex items-center gap-3 rounded-xl bg-slate-50 p-3 text-sm font-semibold"><input type="checkbox" className="h-4 w-4 accent-[#00843d]" checked={editing.verified} onChange={event => setEditing({ ...editing, verified: event.target.checked })}/>Verified sellers only</label><fieldset className="rounded-xl border border-slate-200 p-4"><legend className="px-1 text-sm font-extrabold">Notification settings</legend><label className="mt-1 flex items-start gap-3 text-sm"><input type="checkbox" className="mt-1 h-4 w-4 accent-[#00843d]" checked={editing.notifyInApp} onChange={event => setEditing({ ...editing, notifyInApp: event.target.checked })}/><span><b>In-app notifications</b><span className="block text-xs font-normal text-slate-500">Show matching listings in your Notifications dashboard.</span></span></label><label className="mt-3 flex items-start gap-3 text-sm"><input type="checkbox" className="mt-1 h-4 w-4 accent-[#00843d]" checked={editing.notifyEmail} onChange={event => setEditing({ ...editing, notifyEmail: event.target.checked })}/><span><b>Email notifications</b><span className="block text-xs font-normal text-slate-500">Email delivery is attempted only when the marketplace email provider is configured.</span></span></label></fieldset><div className="flex flex-wrap gap-2"><Button type="submit" className="bg-[#00843d]" disabled={update.isPending}>{update.isPending ? "Saving…" : "Save changes"}</Button><Button type="button" variant="outline" onClick={() => setEditing(null)} disabled={update.isPending}>Cancel</Button></div></form> : <><div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-start gap-3"><div className="rounded-xl bg-[#eaf7ef] p-2.5 text-[#00843d]"><Bell size={18}/></div><div className="min-w-0"><h3 className="break-words text-lg font-extrabold text-[#08243b]">{alert.query}</h3><p className="mt-1 text-sm capitalize text-slate-500">{formatCriteria(alert) || "All marketplace listings"}</p></div></div><span className="shrink-0 rounded-full bg-[#eaf7ef] px-2.5 py-1 text-xs font-black text-[#006b32]">ACTIVE</span></div><div className="mt-5 grid gap-2 border-t border-slate-100 pt-4 text-xs text-slate-500 sm:grid-cols-2"><p className="flex items-center gap-2"><CalendarClock size={14} className="text-[#00843d]"/>Created {new Date(alert.createdAt).toLocaleDateString("en-NG", { day: "numeric", month: "short", year: "numeric" })}</p><p>{alert.lastNotifiedAt ? `Last match ${new Date(alert.lastNotifiedAt).toLocaleDateString("en-NG", { day: "numeric", month: "short" })}` : "No matching listing yet"}</p></div><div className="mt-5 flex flex-wrap gap-2"><Link href={`/explore?q=${encodeURIComponent(alert.query)}`}><Button size="sm" variant="outline">View results</Button></Link><Button size="sm" variant="outline" onClick={() => beginEdit(alert)}><Pencil size={15} className="mr-2"/>Edit alert</Button><Button size="sm" variant="outline" className="text-[#b91c1c] hover:bg-[#fff3f3]" disabled={cancel.isPending} onClick={() => removeAlert(alert.id)}><Trash2 size={15} className="mr-2"/>{cancel.isPending ? "Removing…" : "Remove alert"}</Button></div></>}</article>)}</div> : <div className="mt-4 rounded-3xl border border-dashed border-slate-300 bg-white p-10 text-center"><BellRing className="mx-auto text-[#00843d]" size={30}/><h3 className="mt-3 font-extrabold text-[#08243b]">No active saved searches</h3><p className="mx-auto mt-1 max-w-md text-sm leading-6 text-slate-500">When a search returns no results, choose Notify me to save it here and receive a dashboard alert when new matching items are published.</p><Link href="/explore"><Button className="mt-5 bg-[#e31b23]">Browse the marketplace</Button></Link></div>}</section></main></Gate>;
}
export function BuyerReminderDashboardPage() {
  type ReminderType = "TOMORROW" | "THREE_DAYS" | "ONE_WEEK" | "CUSTOM";
  type ReminderFilter = "ACTIVE" | "HISTORY" | "ALL";
  type ReminderSort = "DUE" | "NEWEST";
  const reminders = trpc.reminders.listMine.useQuery(); const utils = trpc.useUtils(); const [filter, setFilter] = useState<ReminderFilter>("ACTIVE"); const [sort, setSort] = useState<ReminderSort>("DUE"); const [editing, setEditing] = useState<{ id: number; reminderType: ReminderType; scheduledFor: string; note: string } | null>(null);
  const refresh = () => { void utils.reminders.listMine.invalidate(); void utils.reminders.forListing.invalidate(); void utils.notifications.unreadCount.invalidate(); };
  const update = trpc.reminders.update.useMutation({ onSuccess: () => { toast.success("Reminder rescheduled."); setEditing(null); refresh(); }, onError: error => toast.error(error.message) }); const cancel = trpc.reminders.cancel.useMutation({ onSuccess: () => { toast.success("Reminder cancelled."); refresh(); }, onError: error => toast.error(error.message) }); const remove = trpc.reminders.delete.useMutation({ onSuccess: () => { toast.success("Reminder removed."); refresh(); }, onError: error => toast.error(error.message) });
  const localDateTime = (date: Date) => new Date(date.getTime() - date.getTimezoneOffset() * 60_000).toISOString().slice(0, 16);
  const rows = reminders.data ?? []; const activeCount = rows.filter(row => row.reminder.status === "ACTIVE").length; const dueSoon = rows.filter(row => row.reminder.status === "ACTIVE" && new Date(row.reminder.scheduledFor).getTime() <= Date.now() + 48 * 60 * 60 * 1_000).length; const unavailable = rows.filter(row => row.reminder.status === "UNAVAILABLE" || row.availability.status === "UNAVAILABLE").length;
  const visibleRows = rows.filter(row => filter === "ALL" || (filter === "ACTIVE" ? row.reminder.status === "ACTIVE" : row.reminder.status !== "ACTIVE")).sort((left, right) => sort === "DUE" ? new Date(left.reminder.scheduledFor).getTime() - new Date(right.reminder.scheduledFor).getTime() : new Date(right.reminder.createdAt).getTime() - new Date(left.reminder.createdAt).getTime());
  const labels: Record<ReminderFilter, string> = { ACTIVE: "Active", HISTORY: "History", ALL: "All" };
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#e31b23]">MY ACCOUNT</p><div className="mt-2 flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h1 className="text-3xl font-extrabold">Active product reminders</h1><p className="mt-2 max-w-2xl text-sm text-slate-600">Track products you want to revisit. Reminders never reserve stock or create an order.</p></div><Link href="/explore"><Button className="bg-[#e31b23]">Browse products</Button></Link></div><section className="mt-7 grid gap-3 sm:grid-cols-3"><article className="rounded-2xl bg-[#eaf7ef] p-5"><p className="text-sm font-bold text-[#006b32]">Active reminders</p><p className="mt-2 text-3xl font-extrabold">{activeCount}</p></article><article className="rounded-2xl bg-[#fff7e6] p-5"><p className="text-sm font-bold text-[#8a6400]">Due within 48 hours</p><p className="mt-2 text-3xl font-extrabold">{dueSoon}</p></article><article className="rounded-2xl bg-slate-100 p-5"><p className="text-sm font-bold text-slate-600">Need attention</p><p className="mt-2 text-3xl font-extrabold">{unavailable}</p></article></section><section className="mt-6"><div className="flex flex-col gap-3 rounded-2xl bg-white p-4 shadow-sm ring-1 ring-slate-200 sm:flex-row sm:items-center sm:justify-between"><div role="group" aria-label="Reminder status filters" className="flex flex-wrap gap-2">{(Object.keys(labels) as ReminderFilter[]).map(value => <button type="button" key={value} aria-pressed={filter === value} onClick={() => setFilter(value)} className={`rounded-full px-3 py-2 text-sm font-extrabold transition focus:outline-none focus:ring-2 focus:ring-[#00843d]/30 ${filter === value ? "bg-[#08243b] text-white" : "bg-slate-50 text-slate-700 ring-1 ring-slate-200 hover:ring-[#00843d]/40"}`}>{labels[value]}</button>)}</div><label className="text-sm font-bold text-slate-700">Sort <select value={sort} onChange={event => setSort(event.target.value as ReminderSort)} className="ml-2 rounded-lg border bg-white px-3 py-2 font-semibold"><option value="DUE">Next due</option><option value="NEWEST">Recently added</option></select></label></div>{reminders.isLoading ? <p className="mt-4 rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading your reminder dashboard…</p> : reminders.isError ? <div className="mt-4 rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load your reminders.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => reminders.refetch()}>Try again</Button></div> : visibleRows.length ? <div className="mt-4 grid gap-4 lg:grid-cols-2">{visibleRows.map(({ reminder, listing, store, image, availability }) => <article key={reminder.id} className="overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200"><div className="flex gap-4 p-5">{image?.url ? <img src={image.url} alt={image.altText || listing.title} className="h-20 w-20 rounded-xl object-cover"/> : <div className="h-20 w-20 rounded-xl bg-[#eaf7ef]"/>}<div className="min-w-0 flex-1"><div className="flex flex-wrap items-start justify-between gap-2"><p className="font-extrabold">{listing.title}</p><span className={`rounded-full px-2.5 py-1 text-xs font-black ${reminder.status === "ACTIVE" ? "bg-[#eaf7ef] text-[#006b32]" : "bg-slate-100 text-slate-600"}`}>{reminder.status.replaceAll("_", " ")}</span></div><p className="mt-1 text-sm text-slate-500">{store?.name ?? "Original store unavailable"} · {naira(listing.priceKobo)}</p><p className="mt-2 text-sm font-bold text-[#006b32]">{reminder.status === "ACTIVE" ? `Due ${new Date(reminder.scheduledFor).toLocaleString()}` : reminder.status === "TRIGGERED" ? "Reminder was sent" : reminder.status === "CANCELLED" ? "Reminder cancelled" : "Product currently unavailable"}</p><p className="mt-1 text-xs text-slate-500">{availability.status === "IN_STOCK" ? `${availability.availableUnits} in stock` : availability.status === "LOW_STOCK" ? `${availability.availableUnits} left — low stock` : "Currently unavailable"}</p>{reminder.note && <p className="mt-2 rounded-lg bg-slate-50 p-2 text-xs text-slate-600">Note: {reminder.note}</p>}</div></div>{editing?.id === reminder.id ? <form onSubmit={event => { event.preventDefault(); update.mutate({ id: reminder.id, reminderType: editing.reminderType, scheduledFor: editing.reminderType === "CUSTOM" ? new Date(editing.scheduledFor) : undefined, note: editing.note || undefined }); }} className="border-t bg-[#fff7e6] p-5"><label className="block text-sm font-bold">New timing<select value={editing.reminderType} onChange={event => setEditing({ ...editing, reminderType: event.target.value as ReminderType })} className="mt-2 w-full rounded-xl border bg-white p-3"><option value="TOMORROW">Tomorrow</option><option value="THREE_DAYS">In 3 days</option><option value="ONE_WEEK">In 1 week</option><option value="CUSTOM">Choose date &amp; time</option></select></label>{editing.reminderType === "CUSTOM" && <label className="mt-3 block text-sm font-bold">Date and time<input required type="datetime-local" value={editing.scheduledFor} onChange={event => setEditing({ ...editing, scheduledFor: event.target.value })} className="mt-2 w-full rounded-xl border bg-white p-3"/></label>}<label className="mt-3 block text-sm font-bold">Optional note<input value={editing.note} maxLength={500} onChange={event => setEditing({ ...editing, note: event.target.value })} className="mt-2 w-full rounded-xl border bg-white p-3"/></label><div className="mt-4 flex gap-2"><Button size="sm" className="bg-[#00843d]" disabled={update.isPending}>{update.isPending ? "Saving…" : "Save reminder"}</Button><Button type="button" size="sm" variant="outline" onClick={() => setEditing(null)}>Cancel</Button></div></form> : <div className="flex flex-wrap gap-2 border-t p-4">{listing.status === "ACTIVE" && store?.status === "ACTIVE" ? <Link href={`/product/${listing.slug}`}><Button size="sm" className="bg-[#00843d]">View product</Button></Link> : <Link href={store?.status === "ACTIVE" ? `/store/${store.slug}` : `/explore?q=${encodeURIComponent(listing.title)}`}><Button size="sm" variant="outline">{store?.status === "ACTIVE" ? "View store" : "See similar"}</Button></Link>}{reminder.status === "ACTIVE" && <><Button size="sm" variant="outline" onClick={() => setEditing({ id: reminder.id, reminderType: reminder.reminderType, scheduledFor: localDateTime(new Date(reminder.scheduledFor)), note: reminder.note ?? "" })}>Reschedule</Button><Button size="sm" variant="outline" disabled={cancel.isPending} onClick={() => cancel.mutate({ id: reminder.id })}>Cancel reminder</Button></>}{reminder.status !== "ACTIVE" && <Button size="sm" variant="outline" disabled={remove.isPending} onClick={() => remove.mutate({ id: reminder.id })}>Delete</Button>}</div>}</article>)}</div> : <div className="mt-4 rounded-2xl border border-dashed border-slate-300 bg-white p-8 text-center"><Bell className="mx-auto text-[#00843d]"/><p className="mt-3 font-extrabold">{filter === "ACTIVE" ? "No active product reminders" : "No matching reminders"}</p><p className="mt-1 text-sm text-slate-500">Use Remind Me from any product page when you are not ready to buy.</p><Link href="/explore"><Button className="mt-5 bg-[#e31b23]">Browse products</Button></Link></div>}</section></main></Gate>;
}

export function BuyerOffersPage() {
  const offers = trpc.offers.buyerList.useQuery(); const utils = trpc.useUtils(); const cancel = trpc.offers.cancel.useMutation({ onSuccess: () => { toast.success("Offer cancelled."); utils.offers.buyerList.invalidate(); }, onError: error => toast.error(error.message) });
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#e31b23]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">My offers</h1><section className="mt-7 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">{offers.isLoading ? <p className="p-8 text-center text-slate-500">Loading your offers…</p> : offers.isError ? <div className="p-8 text-center text-[#b91c1c]"><p>We could not load your offers.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => offers.refetch()}>Try again</Button></div> : offers.data?.length ? <div className="divide-y">{offers.data.map(({ offer, listing, store }) => <div key={offer.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-extrabold">{listing.title}</p><p className="mt-1 text-sm text-slate-500">{store.name} · {offer.quantity} item(s) · {naira(offer.amountKobo)}</p></div><div className="flex items-center gap-3"><span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold">{format(offer.status)}</span>{["PENDING", "COUNTERED"].includes(offer.status) && <Button size="sm" variant="outline" disabled={cancel.isPending} onClick={() => cancel.mutate({ id: offer.id })}>Cancel</Button>}</div></div>)}</div> : <p className="p-8 text-center text-slate-500">Offers you make on eligible products will appear here.</p>}</section></main></Gate>;
}

export function NotificationsPage() {
  type NotificationFilter = "ALL" | "UNREAD" | "READ";
  const [filter, setFilter] = useState<NotificationFilter>("ALL"); const notices = trpc.notifications.list.useQuery({ page: 1, limit: MARKETPLACE_PAGE_SIZE, filter }); const unread = trpc.notifications.unreadCount.useQuery(); const utils = trpc.useUtils(); const refresh = () => { utils.notifications.list.invalidate(); utils.notifications.unreadCount.invalidate(); }; const read = trpc.notifications.markRead.useMutation({ onSuccess: refresh, onError: error => toast.error(error.message) }); const markAll = trpc.notifications.markAllRead.useMutation({ onSuccess: () => { toast.success("All notifications marked as read."); refresh(); }, onError: error => toast.error(error.message) }); const labels: Record<NotificationFilter, string> = { ALL: "All", UNREAD: "Unread", READ: "Read" };
  return <Gate><main className="page-shell py-8"><Link href="/account" className="inline-flex items-center text-sm font-bold text-[#00843d] underline-offset-4 hover:underline">← Back to account</Link><p className="eyebrow mt-5 text-[#00843d]">MY ACCOUNT</p><div className="mt-2 flex flex-wrap items-center justify-between gap-3"><div><h1 className="text-3xl font-extrabold">Notifications</h1><p className="mt-2 text-sm text-slate-500">Manage alerts from your orders, seller journey, messages, and pickup activity.</p></div>{unread.data?.count ? <Button variant="outline" size="sm" disabled={markAll.isPending} onClick={() => markAll.mutate()}>Mark all read ({unread.data.count})</Button> : null}</div><div role="group" aria-label="Notification filters" className="mt-6 flex flex-wrap gap-2">{(Object.keys(labels) as NotificationFilter[]).map(value => <button type="button" key={value} aria-pressed={filter === value} onClick={() => setFilter(value)} className={`rounded-full px-4 py-2 text-sm font-extrabold transition focus:outline-none focus:ring-2 focus:ring-[#00843d]/30 ${filter === value ? "bg-[#08243b] text-white" : "bg-white text-slate-700 ring-1 ring-slate-200 hover:ring-[#00843d]/40"}`}>{labels[value]}{value === "UNREAD" && unread.data?.count ? ` (${unread.data.count})` : ""}</button>)}</div><section className="mt-4 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">{notices.isLoading ? <p className="p-8 text-center text-slate-500">Loading notifications…</p> : notices.isError ? <div className="p-8 text-center text-[#b91c1c]"><p>We could not load notifications.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => notices.refetch()}>Try again</Button></div> : notices.data?.length ? <div className="divide-y">{notices.data.map(notification => <article key={notification.id} className={`flex items-start gap-4 p-5 transition ${notification.isRead ? "" : "bg-[#eaf7ef]/60"}`}><Bell className="mt-0.5 shrink-0 text-[#00843d]" size={18} /><div className="min-w-0 flex-1"><Link href={notification.targetRoute ?? "/account/notifications"} className="block rounded-lg focus:outline-none focus:ring-2 focus:ring-[#00843d]/30"><p className="font-extrabold">{notification.title}</p><p className="mt-1 text-sm text-slate-600">{notification.message}</p><p className="mt-2 text-xs text-slate-400">{new Date(notification.createdAt).toLocaleString()}</p></Link><div className="mt-3 flex items-center gap-3"><span className={`text-xs font-black uppercase tracking-[.1em] ${notification.isRead ? "text-slate-400" : "text-[#006b32]"}`}>{notification.isRead ? "Read" : "Unread"}</span>{!notification.isRead && <Button type="button" size="sm" variant="outline" disabled={read.isPending} onClick={() => read.mutate({ id: notification.id })}>Mark as read</Button>}</div></div></article>)}</div> : <p className="p-8 text-center text-slate-500">{filter === "UNREAD" ? "You’re all caught up." : filter === "READ" ? "No read notifications yet." : "You have no notifications yet."}</p>}</section></main></Gate>;
}

export function BuyerReviewsPage() {
  const mine = trpc.reviews.mine.useQuery(); const eligible = trpc.reviews.eligible.useQuery(); const repurchase = trpc.buyer.repurchaseCandidates.useQuery(); const utils = trpc.useUtils();
  const [rating, setRating] = useState(5); const [title, setTitle] = useState(""); const [comment, setComment] = useState(""); const [selected, setSelected] = useState<{ orderId: number; listingId: number } | null>(null); const [mediaFiles, setMediaFiles] = useState<File[]>([]);
  const create = trpc.reviews.create.useMutation({ onSuccess: () => { toast.success("Verified purchase review published."); setSelected(null); setTitle(""); setComment(""); setMediaFiles([]); void utils.reviews.mine.invalidate(); void utils.reviews.eligible.invalidate(); }, onError: error => toast.error(error.message) });
  const buyAgain = trpc.cart.add.useMutation({ onSuccess: () => { toast.success("Current listing added to your cart."); void utils.cart.get.invalidate(); }, onError: error => toast.error(error.message) });
  const selectReviewMedia = (event: React.ChangeEvent<HTMLInputElement>) => { const selectedFiles = Array.from(event.target.files ?? []); event.target.value = ""; if (!selectedFiles.length) return; if (selectedFiles.some(file => !reviewPhotoTypes.has(file.type) || file.size > 3 * 1024 * 1024)) return toast.error("Review images must be JPEG, PNG, or WebP and 3 MB or smaller."); const unique = new Map(mediaFiles.map(file => [`${file.name}:${file.size}:${file.lastModified}`, file])); selectedFiles.forEach(file => unique.set(`${file.name}:${file.size}:${file.lastModified}`, file)); const next = Array.from(unique.values()); if (next.length > 4) return toast.error("You can attach up to four review images."); setMediaFiles(next); };
  const submitReview = async () => { if (!selected) return; try { const media = await Promise.all(mediaFiles.map(readReviewPhoto)); create.mutate({ ...selected, rating, title: title || undefined, comment: comment || undefined, media: media.length ? media : undefined }); } catch (error) { toast.error(error instanceof Error ? error.message : "The review images could not be prepared."); } };
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#e31b23]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">Reviews</h1><section className="mt-7 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Eligible completed purchases</h2>{eligible.isLoading ? <p className="mt-3 text-sm text-slate-500">Loading eligible purchases…</p> : eligible.isError ? <div className="mt-3 text-sm text-[#b91c1c]"><p>We could not load eligible purchases.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => eligible.refetch()}>Try again</Button></div> : eligible.data?.length ? <div className="mt-4 divide-y">{eligible.data.map(({ order, item, listing }) => <div key={`${order.id}:${item.listingId}`} className="flex items-center justify-between gap-4 py-4"><div><p className="font-bold">{listing.title}</p><p className="text-sm text-slate-500">Order {order.publicId}</p></div><Button size="sm" onClick={() => { setSelected({ orderId: order.id, listingId: item.listingId }); setMediaFiles([]); }}><Star size={16} />Write review</Button></div>)}</div> : <p className="mt-3 text-sm text-slate-500">Complete a campus-pickup order before leaving a verified review.</p>}</section>{selected && <section className="mt-6 rounded-2xl bg-[#fff7e6] p-6 ring-1 ring-[#f5b700]/30"><h2 className="font-extrabold">Write a verified review</h2><p className="mt-1 text-sm text-slate-600">Your rating remains tied to this completed marketplace order. Images are optional and are validated by the server.</p><div className="mt-4 flex gap-2">{[1,2,3,4,5].map(value => <button type="button" key={value} onClick={() => setRating(value)} className={value <= rating ? "text-[#f5b700]" : "text-slate-300"} aria-label={`${value} star rating`}><Star fill="currentColor" /></button>)}</div><input value={title} maxLength={180} onChange={event => setTitle(event.target.value)} className="mt-4 w-full rounded-xl border p-3" placeholder="Optional review title"/><textarea value={comment} onChange={event => setComment(event.target.value)} className="mt-3 min-h-28 w-full rounded-xl border p-3" placeholder="Share your completed-order experience." /><div className="mt-3 rounded-xl border border-dashed border-[#00843d]/35 bg-white/70 p-4"><label className="block text-sm font-bold text-slate-800">Optional review images<input type="file" multiple accept="image/jpeg,image/png,image/webp" onChange={selectReviewMedia} className="mt-2 block w-full text-sm font-normal" /></label><p className="mt-2 text-xs leading-5 text-slate-500">Up to four JPEG, PNG, or WebP images; 3 MB maximum per image. Do not include private documents or unrelated people.</p>{mediaFiles.length ? <ul className="mt-3 space-y-1 text-xs text-slate-600">{mediaFiles.map((file, index) => <li className="flex items-center justify-between gap-3" key={`${file.name}-${index}`}><span className="truncate">{file.name} · {(file.size / (1024 * 1024)).toFixed(1)} MB</span><button type="button" className="font-bold text-[#b91c1c] hover:underline" onClick={() => setMediaFiles(current => current.filter((_, currentIndex) => currentIndex !== index))}>Remove</button></li>)}</ul> : null}</div><div className="mt-4 flex flex-wrap gap-2"><Button className="bg-[#00843d]" disabled={create.isPending} onClick={() => void submitReview()}>{create.isPending ? "Publishing review…" : "Submit review"}</Button><Button type="button" variant="outline" disabled={create.isPending} onClick={() => { setSelected(null); setMediaFiles([]); }}>Cancel</Button></div></section>}<section className="mt-6 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Published reviews</h2>{mine.isLoading ? <p className="mt-3 text-sm text-slate-500">Loading your published reviews…</p> : mine.isError ? <div className="mt-3 text-sm text-[#b91c1c]"><p>We could not load your published reviews.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => mine.refetch()}>Try again</Button></div> : mine.data?.length ? <div className="mt-4 divide-y">{mine.data.map(({ review, listing }) => <div className="py-4" key={review.id}><p className="font-bold">{listing.title} · {"★".repeat(review.rating)}</p>{review.title && <p className="mt-1 font-semibold text-slate-700">{review.title}</p>}<p className="mt-1 text-sm text-slate-600">{review.comment ?? "No written comment."}</p></div>)}</div> : <p className="mt-3 text-sm text-slate-500">Your submitted reviews will appear here.</p>}</section><section className="mt-6 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Buy again</h2><p className="mt-1 text-sm text-slate-500">We use today’s product, seller, price, and stock—not your old order price.</p>{repurchase.isLoading ? <p className="mt-4 text-sm text-slate-500">Checking your previous purchases…</p> : repurchase.data?.length ? <div className="mt-4 divide-y">{repurchase.data.slice(0, 8).map(({ listing, store, availability, canBuyAgain }) => <div className="flex flex-wrap items-center justify-between gap-3 py-4" key={listing.id}><div><p className="font-bold">{listing.title}</p><p className="mt-1 text-sm text-slate-500">{store.name} · {naira(listing.priceKobo)} · {availability.availableUnits ? `${availability.availableUnits} available` : "Currently unavailable"}</p></div>{canBuyAgain ? <Button size="sm" className="bg-[#00843d]" disabled={buyAgain.isPending} onClick={() => buyAgain.mutate({ listingId: listing.id, quantity: 1 })}>Buy again</Button> : <Link href="/account/reminders"><Button size="sm" variant="outline">Set reminder</Button></Link>}</div>)}</div> : <p className="mt-4 text-sm text-slate-500">Completed purchases with current listings will appear here.</p>}</section></main></Gate>;
}

export function ProfilePage() {
  const profile = trpc.profile.get.useQuery(); const utils = trpc.useUtils(); const [form, setForm] = useState({ phone: "", location: "", bio: "" }); const update = trpc.profile.update.useMutation({ onSuccess: () => { toast.success("Profile updated."); utils.profile.get.invalidate(); }, onError: error => toast.error(error.message) }); const data = profile.data;
  return <Gate><main className="page-shell py-8"><Link href="/account" className="inline-flex items-center text-sm font-bold text-[#00843d] underline-offset-4 hover:underline">← Back to account</Link><p className="eyebrow mt-5 text-[#00843d]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">Profile</h1>{profile.isLoading ? <section className="mt-7 max-w-xl rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading your profile…</section> : profile.isError ? <section className="mt-7 max-w-xl rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load your profile.</p><Button variant="outline" className="mt-4" onClick={() => profile.refetch()}>Try again</Button></section> : <form onSubmit={event => { event.preventDefault(); update.mutate({ phone: form.phone || data?.phone || undefined, location: form.location || data?.location || undefined, bio: form.bio || data?.bio || undefined }); }} className="mt-7 max-w-xl rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><label className="block text-sm font-bold">Phone<input value={form.phone} placeholder={data?.phone ?? "Phone number"} onChange={event => setForm({ ...form, phone: event.target.value })} className="mt-2 w-full rounded-xl border p-3" /></label><label className="mt-5 block text-sm font-bold">Campus location<input value={form.location} placeholder={data?.location ?? "Location"} onChange={event => setForm({ ...form, location: event.target.value })} className="mt-2 w-full rounded-xl border p-3" /></label><label className="mt-5 block text-sm font-bold">Bio<textarea value={form.bio} placeholder={data?.bio ?? "Tell buyers and sellers about yourself"} onChange={event => setForm({ ...form, bio: event.target.value })} className="mt-2 min-h-28 w-full rounded-xl border p-3" /></label><Button className="mt-6 bg-[#00843d]" disabled={update.isPending}><Pencil size={16} />{update.isPending ? "Saving profile…" : "Save profile"}</Button></form>}</main></Gate>;
}

export function AccountVerificationPage() { const profile = trpc.profile.get.useQuery(); return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#00843d]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">Seller verification</h1>{profile.isLoading ? <section className="mt-7 max-w-xl rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading verification status…</section> : profile.isError ? <section className="mt-7 max-w-xl rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load your verification status.</p><Button variant="outline" className="mt-4" onClick={() => profile.refetch()}>Try again</Button></section> : <section className="mt-7 max-w-xl rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><ShieldCheck className="text-[#00843d]" size={32} /><h2 className="mt-4 font-extrabold">Current status: {profile.data?.verificationStatus ?? "UNVERIFIED"}</h2><p className="mt-2 text-sm text-slate-600">Individual and business sellers must pass verification before submitting a store application or accessing sensitive seller tools.</p><Link href="/sell"><Button className="mt-6 bg-[#e31b23]">Open seller verification</Button></Link></section>}</main></Gate>; }

export function MessagesPage({ seller = false }: { seller?: boolean }) {
  const conversations = trpc.messaging.list.useQuery();
  const [, params] = useRoute(seller ? "/seller/messages/:id" : "/account/messages/:id");
  const conversationId = Number(params?.id);
  const detail = trpc.messaging.detail.useQuery({ conversationId }, { enabled: Number.isFinite(conversationId) });
  const [body, setBody] = useState("");
  const utils = trpc.useUtils();
  const send = trpc.messaging.send.useMutation({ onSuccess: () => { setBody(""); void utils.messaging.detail.invalidate({ conversationId }); void utils.messaging.list.invalidate(); toast.success("Message sent."); }, onError: error => toast.error(error.message) });
  const base = seller ? "/seller/messages" : "/account/messages";
  const detailContent = !Number.isFinite(conversationId) ? <p className="text-slate-500">Choose a conversation to read and reply.</p> : detail.isLoading ? <p className="text-slate-500">Loading messages…</p> : detail.isError ? <div className="text-center text-[#b91c1c]"><p>We could not load this conversation.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => detail.refetch()}>Try again</Button></div> : !detail.data ? <p className="text-slate-500">This conversation is unavailable.</p> : <><div className="space-y-4">{detail.data.messages.length ? detail.data.messages.map(({ message, sender }) => <div key={message.id} className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-bold text-[#00843d]">{sender.name ?? "Marketplace member"}</p><p className="mt-1 text-sm">{message.body}</p><CaseReportButton targetType="MESSAGE" targetId={message.id} subjectLabel="A message in this private conversation" buttonLabel="Report message" className="mt-2 h-auto border-0 bg-transparent px-0 py-0 text-xs font-bold text-slate-500 shadow-none hover:bg-transparent hover:text-[#e31b23]" /></div>) : <p className="rounded-xl bg-slate-50 p-4 text-sm text-slate-500">No messages have been sent in this conversation yet.</p>}</div><form onSubmit={event => { event.preventDefault(); if (body.trim()) send.mutate({ conversationId, body }); }} className="mt-6"><textarea value={body} onChange={event => setBody(event.target.value)} className="min-h-24 w-full rounded-xl border p-3" placeholder="Write a message" /><Button className="mt-3 bg-[#00843d]" disabled={send.isPending}><MessageCircle size={16} />{send.isPending ? "Sending…" : "Send"}</Button></form></>;
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#00843d]">{seller ? "SELLER" : "MY ACCOUNT"}</p><h1 className="mt-2 text-3xl font-extrabold">Messages</h1><div className="mt-7 grid gap-5 lg:grid-cols-[300px_1fr]"><aside className="rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">{conversations.isLoading ? <p className="p-5 text-sm text-slate-500">Loading conversations…</p> : conversations.isError ? <div className="p-5 text-center text-sm text-[#b91c1c]"><p>We could not load conversations.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => conversations.refetch()}>Try again</Button></div> : conversations.data?.length ? conversations.data.map(({ conversation, listing, store, counterparty, latestMessage }) => <Link key={conversation.id} href={`${base}/${conversation.id}`} className="block border-b p-4 transition hover:bg-slate-50"><div className="flex items-start justify-between gap-2"><p className="truncate font-extrabold text-[#111827]">{counterparty?.name ?? "Marketplace member"}</p>{latestMessage ? <time className="shrink-0 text-[10px] text-slate-400">{new Date(latestMessage.createdAt).toLocaleDateString()}</time> : null}</div><p className="mt-1 truncate text-xs font-semibold text-[#00843d]">{listing.title} · {store.name}</p><p className="mt-1 line-clamp-2 text-xs text-slate-500">{latestMessage ? `${latestMessage.isMine ? "You: " : ""}${latestMessage.body}` : "No messages have been sent yet."}</p></Link>) : <p className="p-5 text-sm text-slate-500">No conversations yet.</p>}</aside><section className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200">{detailContent}</section></div></main></Gate>;
}

export function SellerOffersPage() { const offers = trpc.offers.sellerList.useQuery(); const utils = trpc.useUtils(); const respond = trpc.offers.respond.useMutation({ onSuccess: () => { toast.success("Offer updated."); utils.offers.sellerList.invalidate(); }, onError: error => toast.error(error.message) }); return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#00843d]">SELLER</p><h1 className="mt-2 text-3xl font-extrabold">Buyer offers</h1><section className="mt-7 overflow-hidden rounded-2xl bg-white shadow-sm ring-1 ring-slate-200">{offers.isLoading ? <p className="p-8 text-center text-slate-500">Loading buyer offers…</p> : offers.isError ? <div className="p-8 text-center text-[#b91c1c]"><p>We could not load buyer offers.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => offers.refetch()}>Try again</Button></div> : offers.data?.length ? <div className="divide-y">{offers.data.map(({ offer, listing, buyer }) => <div key={offer.id} className="flex flex-col gap-3 p-5 sm:flex-row sm:items-center sm:justify-between"><div><p className="font-extrabold">{listing.title}</p><p className="mt-1 text-sm text-slate-500">Buyer: {buyer.name ?? "Marketplace member"} · {naira(offer.amountKobo)}</p></div><div className="flex gap-2">{["PENDING", "COUNTERED"].includes(offer.status) ? <><Button size="sm" className="bg-[#00843d]" disabled={respond.isPending} onClick={() => respond.mutate({ id: offer.id, status: "ACCEPTED", note: "Offer accepted." })}>Accept</Button><Button size="sm" variant="outline" disabled={respond.isPending} onClick={() => respond.mutate({ id: offer.id, status: "REJECTED", note: "Offer declined." })}>Reject</Button></> : <span className="rounded-full bg-slate-100 px-2.5 py-1 text-xs font-bold">{format(offer.status)}</span>}</div></div>)}</div> : <p className="p-8 text-center text-slate-500">Buyer offers will appear here.</p>}</section></main></Gate>; }

export function SellerReviewsPage() { const reviews = trpc.reviews.sellerList.useQuery(); const utils = trpc.useUtils(); const [response, setResponse] = useState<Record<number, string>>({}); const respond = trpc.reviews.respond.useMutation({ onSuccess: () => { toast.success("Review response saved."); utils.reviews.sellerList.invalidate(); }, onError: error => toast.error(error.message) }); return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#00843d]">SELLER</p><h1 className="mt-2 text-3xl font-extrabold">Verified buyer reviews</h1><section className="mt-7 space-y-4">{reviews.isLoading ? <p className="rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading verified buyer reviews…</p> : reviews.isError ? <div className="rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load buyer reviews.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => reviews.refetch()}>Try again</Button></div> : reviews.data?.length ? reviews.data.map(({ review, listing, buyer }) => <article key={review.id} className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><p className="font-extrabold">{listing.title} · {"★".repeat(review.rating)}</p><p className="mt-1 text-sm text-slate-500">Buyer: {buyer.name ?? "Marketplace member"}</p><p className="mt-4">{review.comment ?? "No written comment."}</p>{review.sellerResponse ? <p className="mt-4 rounded-xl bg-[#eaf7ef] p-3 text-sm"><b>Your response:</b> {review.sellerResponse}</p> : <div className="mt-4"><textarea value={response[review.id] ?? ""} onChange={event => setResponse({ ...response, [review.id]: event.target.value })} className="min-h-20 w-full rounded-xl border p-3" placeholder="Write a professional response" /><Button size="sm" className="mt-3 bg-[#00843d]" disabled={respond.isPending || !(response[review.id] ?? "").trim()} onClick={() => respond.mutate({ id: review.id, response: response[review.id] ?? "" })}>{respond.isPending ? "Saving response…" : "Respond"}</Button></div>}</article>) : <p className="rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Verified buyer reviews will appear here after completed orders.</p>}</section></main></Gate>; }

export function AccountSupportPage() { const reports = trpc.support.myReports.useQuery(); const disputes = trpc.support.myDisputes.useQuery(); return <Gate><main className="page-shell py-8"><Link href="/account" className="inline-flex items-center text-sm font-bold text-[#00843d] underline-offset-4 hover:underline">← Back to account</Link><p className="eyebrow mt-5 text-[#e31b23]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">Safety and support</h1><p className="mt-2 max-w-2xl text-slate-600">Your submitted reports and active order disputes are handled through protected marketplace workflows.</p><section className="mt-7 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div className="flex items-center gap-2"><Flag className="text-[#e31b23]"/><h2 className="font-extrabold">My reports</h2></div>{reports.isLoading ? <p className="mt-4 text-sm text-slate-500">Loading your reports…</p> : reports.isError ? <div className="mt-4 text-sm text-[#b91c1c]"><p>We could not load your reports.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => reports.refetch()}>Try again</Button></div> : reports.data?.length ? <div className="mt-4 divide-y">{reports.data.map(report => <div className="py-4" key={report.id}><p className="font-bold">{report.reason}</p><p className="mt-1 text-sm text-slate-500">{report.targetType} #{report.targetId} · {format(report.status)}</p><p className="mt-1 text-sm text-slate-600">{report.resolutionNote ?? "Awaiting administrator review."}</p></div>)}</div> : <p className="mt-4 text-sm text-slate-500">No reports have been submitted from your account.</p>}</section><section className="mt-6 rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div className="flex items-center gap-2"><Gavel className="text-[#00843d]"/><h2 className="font-extrabold">My order disputes</h2></div>{disputes.isLoading ? <p className="mt-4 text-sm text-slate-500">Loading your disputes…</p> : disputes.isError ? <div className="mt-4 text-sm text-[#b91c1c]"><p>We could not load your disputes.</p><Button variant="outline" size="sm" className="mt-3" onClick={() => disputes.refetch()}>Try again</Button></div> : disputes.data?.length ? <div className="mt-4 divide-y">{disputes.data.map(({ dispute, order, store }) => <Link href={`/account/orders/${order.publicId}`} className="block rounded-xl py-4 transition hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-[#00843d]/30" key={dispute.id}><p className="font-bold">Order {order.publicId} · {dispute.reason}</p><p className="mt-1 text-sm text-slate-500">{store.name} · {format(dispute.status)}</p><p className="mt-1 text-sm text-slate-600">{dispute.resolution ?? "Awaiting an administrator resolution."}</p><span className="mt-2 inline-block text-xs font-extrabold text-[#00843d]">View protected order details →</span></Link>)}</div> : <p className="mt-4 text-sm text-slate-500">No order disputes are associated with your account.</p>}</section></main></Gate>; }

function AccountPasswordField({ id, label, value, onChange, minLength = 10, placeholder }: { id: string; label: string; value: string; onChange: (value: string) => void; minLength?: number; placeholder: string }) { const [visible, setVisible] = useState(false); return <label className="block text-sm font-bold" htmlFor={id}>{label}<span className="relative mt-2 block"><LockKeyhole className="pointer-events-none absolute left-3 top-3 text-slate-400" size={18}/><input id={id} type={visible ? "text" : "password"} required minLength={minLength} autoComplete={id === "current-password" ? "current-password" : "new-password"} value={value} onChange={event => onChange(event.target.value)} placeholder={placeholder} className="h-11 w-full rounded-xl border border-slate-300 py-2 pl-10 pr-11 text-sm shadow-sm outline-none transition focus:border-[#00843d] focus:ring-2 focus:ring-[#00843d]/20"/><button type="button" onClick={() => setVisible(previous => !previous)} aria-label={visible ? `Hide ${label.toLowerCase()}` : `Show ${label.toLowerCase()}`} className="absolute right-3 top-2.5 rounded p-0.5 text-slate-400 transition hover:text-slate-700 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[#00843d]">{visible ? <EyeOff size={18}/> : <Eye size={18}/>}</button></span></label>; }

export function AccountSettingsPage() {
  const { user, logout, refresh } = useAuth(); const [, navigate] = useLocation(); const profile = trpc.profile.get.useQuery(); const [passwords, setPasswords] = useState({ currentPassword: "", newPassword: "", confirmPassword: "" }); const changePassword = trpc.auth.changePassword.useMutation({ onSuccess: async () => { setPasswords({ currentPassword: "", newPassword: "", confirmPassword: "" }); await refresh(); toast.success("Your password has been changed and your current session was renewed."); }, onError: error => toast.error(error.message) });
  const signOut = async () => { try { await logout(); navigate("/"); toast.success("You have been signed out."); } catch { toast.error("Unable to sign out. Please try again."); } };
  const submitPasswordChange = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); if (passwords.newPassword !== passwords.confirmPassword) return toast.error("New passwords do not match."); if (passwords.currentPassword === passwords.newPassword) return toast.error("Choose a password that is different from your current password."); changePassword.mutate(passwords); };
  const identity = profile.isLoading ? "Loading marketplace identity…" : profile.isError ? "Marketplace identity details are temporarily unavailable." : `${user?.email ?? "No email on this account"} · ${profile.data?.accountType ?? "INDIVIDUAL"} account · verification ${profile.data?.verificationStatus ?? "UNVERIFIED"}`;
  return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#00843d]">MY ACCOUNT</p><h1 className="mt-2 text-3xl font-extrabold">Account settings</h1><section className="mt-7 grid max-w-3xl gap-5"><article className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Profile and marketplace identity</h2><p className={`mt-2 text-sm ${profile.isError ? "text-[#b91c1c]" : "text-slate-600"}`}>{identity}</p>{profile.isError ? <Button variant="outline" size="sm" className="mt-4" onClick={() => profile.refetch()}>Try again</Button> : <Link href="/account/profile" className="mt-4 inline-block text-sm font-bold text-[#00843d]">Edit profile details</Link>}</article><article className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Password and sign-in security</h2><p className="mt-2 text-sm text-slate-600">Confirm your current password, then choose a new password with at least 10 characters. Your browser session is renewed after a successful change.</p><form onSubmit={submitPasswordChange} className="mt-5 grid gap-4" noValidate><AccountPasswordField id="current-password" label="Current password" value={passwords.currentPassword} onChange={currentPassword => setPasswords(previous => ({ ...previous, currentPassword }))} minLength={1} placeholder="Enter your current password"/><AccountPasswordField id="new-password" label="New password" value={passwords.newPassword} onChange={newPassword => setPasswords(previous => ({ ...previous, newPassword }))} placeholder="At least 10 characters"/><AccountPasswordField id="confirm-new-password" label="Confirm new password" value={passwords.confirmPassword} onChange={confirmPassword => setPasswords(previous => ({ ...previous, confirmPassword }))} placeholder="Re-enter your new password"/><p className="text-xs leading-5 text-slate-500">Password recovery by email is currently unavailable while the marketplace uses a restricted test sender. Change your password here while signed in.</p><div className="flex flex-wrap gap-3"><Button type="submit" className="bg-[#00843d] hover:bg-[#006b32]" disabled={changePassword.isPending}>{changePassword.isPending ? "Updating password…" : "Change password"}</Button><Button type="button" variant="outline" className="border-[#e31b23] text-[#e31b23]" onClick={signOut}>Sign out</Button></div></form></article><article className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Marketplace notifications and safety</h2><p className="mt-2 text-sm text-slate-600">Review order, seller, offer, and safety notifications tied to this secure account.</p><div className="mt-4 flex flex-wrap gap-4"><Link href="/account/notifications" className="text-sm font-bold text-[#00843d]">Open notifications</Link><Link href="/account/support" className="text-sm font-bold text-[#00843d]">Safety and support</Link></div></article></section></main></Gate>;
}

export function SellerSettingsPage() { const { user } = useAuth(); const store = trpc.seller.store.useQuery(undefined, { enabled: ["SELLER", "ADMIN", "SUPER_ADMIN"].includes(user?.role ?? "") }); const utils = trpc.useUtils(); const [form, setForm] = useState({ name: "", description: "", location: "", contactPhone: "" }); const update = trpc.seller.updateStore.useMutation({ onSuccess: () => { toast.success("Seller configuration saved."); utils.seller.store.invalidate(); }, onError: error => toast.error(error.message) }); const data = store.data; const storeContent = store.isLoading ? <article className="rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">Loading approved store configuration…</article> : store.isError ? <article className="rounded-2xl bg-[#fff3f3] p-8 text-center text-[#b91c1c] ring-1 ring-[#fecaca]"><p>We could not load your store configuration.</p><Button variant="outline" className="mt-4" onClick={() => store.refetch()}>Try again</Button></article> : !data ? <article className="rounded-2xl bg-white p-8 text-center text-slate-500 shadow-sm ring-1 ring-slate-200">No approved store configuration is available for this account yet.</article> : <form onSubmit={event => { event.preventDefault(); update.mutate({ name: form.name || data.name, description: form.description || data.description || undefined, location: form.location || data.location, contactPhone: form.contactPhone || data.contactPhone || undefined }); }} className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Store configuration</h2><p className="mt-2 text-sm text-slate-600">{data.name} · {data.status} · {data.isVerified ? "Verified" : "Unverified"}</p><label className="mt-5 block text-sm font-bold">Store name<input value={form.name} placeholder={data.name} onChange={event => setForm({ ...form, name: event.target.value })} className="mt-2 w-full rounded-xl border p-3" /></label><label className="mt-4 block text-sm font-bold">Location<input value={form.location} placeholder={data.location} onChange={event => setForm({ ...form, location: event.target.value })} className="mt-2 w-full rounded-xl border p-3" /></label><label className="mt-4 block text-sm font-bold">Contact phone<input value={form.contactPhone} placeholder={data.contactPhone ?? "Contact phone"} onChange={event => setForm({ ...form, contactPhone: event.target.value })} className="mt-2 w-full rounded-xl border p-3" /></label><label className="mt-4 block text-sm font-bold">Store description<textarea value={form.description} placeholder={data.description ?? "Describe your store"} onChange={event => setForm({ ...form, description: event.target.value })} className="mt-2 min-h-24 w-full rounded-xl border p-3" /></label><Button className="mt-5 bg-[#00843d]" disabled={update.isPending}>{update.isPending ? "Saving configuration…" : "Save seller configuration"}</Button></form>; return <Gate><main className="page-shell py-8"><p className="eyebrow text-[#00843d]">SELLER</p><h1 className="mt-2 text-3xl font-extrabold">Seller settings</h1><section className="mt-7 grid max-w-3xl gap-5">{storeContent}<article className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Selling operations</h2><p className="mt-2 text-sm text-slate-600">Keep contact information current, monitor fulfilment, and review buyer communications from the protected seller workspace.</p><div className="mt-4 flex flex-wrap gap-4"><Link href="/seller/orders" className="text-sm font-bold text-[#00843d]">Order operations</Link><Link href="/seller/messages" className="text-sm font-bold text-[#00843d]">Buyer messages</Link><Link href="/seller/reviews" className="text-sm font-bold text-[#00843d]">Buyer reviews</Link></div></article><article className="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><h2 className="font-extrabold">Personal account security</h2><p className="mt-2 text-sm text-slate-600">Account security is managed separately from your store profile.</p><Link href="/account/settings" className="mt-4 inline-block text-sm font-bold text-[#00843d]">Open account settings</Link></article></section></main></Gate>; }
